    this.morphCompletePromise = null
    this.morphCompleteResolver = null
  }

  handleKeydown(event) {
    if (this.#shouldIgnore(event) || this.#hasModifier(event)) return

    const handler = this.#keyHandlers[event.key.toLowerCase()]
    if (handler) {
      handler.call(this, event)
    }
